  let source = Source::new(source)
  @json.inspect(source, content={
    "content": "// Header\n///|\nlet x : Int = 5\n///|\nlet y : String = \\\"hello\\\"\n///|\nfn greet() -> String {\n  y\n}",
    "header": { "start": 0, "end": 1, "content": "// Header" },
    "segments": [
      { "start": 1, "end": 3, "content": "///|\nlet x : Int = 5" },
      {
        "start": 1,
        "end": 5,
        "content": "///|\nlet x : Int = 5\n///|\nlet y : String = \\\"hello\\\"",
      },
      {
        "start": 1,
